import { DatabaseSync } from 'node:sqlite';
const db = new DatabaseSync('/bench/home/work/.codegraph/codegraph.db', { readOnly: true });

// Fan-in by distinct caller nodes (calls edges), target is a function/method under internal/
const q = `
SELECT n.id, n.name, n.qualified_name, n.file_path, n.start_line, n.kind,
       COUNT(DISTINCT e.source) AS distinct_callers,
       COUNT(*) AS total_call_edges
FROM edges e
JOIN nodes n ON n.id = e.target
WHERE e.kind = 'calls'
  AND n.file_path LIKE 'internal/%'
  AND n.kind IN ('function','method')
GROUP BY n.id
ORDER BY distinct_callers DESC
LIMIT 25`;
console.log('symbol | kind | file:line | distinctCallers | totalCallEdges');
for (const r of db.prepare(q).all())
  console.log(`${r.name} | ${r.kind} | ${r.file_path}:${r.start_line} | ${r.distinct_callers} | ${r.total_call_edges}`);

