import { DatabaseSync } from 'node:sqlite';
const db = new DatabaseSync('/bench/home/work/.codegraph/codegraph.db', { readOnly: true });

// For a given target node id, list distinct caller files & how many caller nodes share the target's package dir
function report(name, file) {
  const n = db.prepare("SELECT id,file_path,start_line FROM nodes WHERE file_path=? AND name=?").all(file, name);
  if (!n.length) { console.log(`NOT FOUND ${name} ${file}`); return; }
  const id = n[0].id;
  const pkgDir = file.substring(0, file.lastIndexOf('/'));
  const callers = db.prepare(`SELECT DISTINCT s.file_path FROM edges e JOIN nodes s ON s.id=e.source WHERE e.kind='calls' AND e.target=? ORDER BY s.file_path`).all(id);
  const inPkg = callers.filter(c => c.file_path.startsWith(pkgDir)).length;
  const distinctCallerNodes = db.prepare(`SELECT COUNT(DISTINCT e.source) c FROM edges e WHERE e.kind='calls' AND e.target=?`).get(id).c;
  console.log(`\n### ${name}  (${file}:${n[0].start_line})  distinctCallerNodes=${distinctCallerNodes}  distinctFiles=${callers.length}  filesInPkg=${inPkg}`);
  for (const c of callers) console.log('   ', c.file_path);
}

for (const [nm, f] of [
  ['Next','internal/scheduler/parser.go'],
  ['CompileToStatement','internal/filter/engine.go'],
  ['NewEngine','internal/filter/engine.go'],
  ['NewSchema','internal/filter/schema.go'],
  ['NewService','internal/markdown/markdown.go'],
]) report(nm, f);

